#include "solver.h"
#include "dimacs.h"
#include "elim.h"
#include <assert.h>
#include <stdlib.h>
#include <stdio.h>
int main(int argc,char **argv) {
    assert(argc==2);SolverOpts o=default_opts();o.congruence=true;o.equiv=true;
    o.equiv_budget=100000000;o.alternating=true;o.vmtf=true;o.max_conflicts=1;
    Solver *s=solver_new_with_opts(&o);assert(s);
    assert(dimacs_parse_file(s,argv[1])==DIMACS_OK);
    lbool result=solver_solve(s);assert(!s->error);
    unsigned char *present=calloc((size_t)s->num_vars+1,1),*open=calloc((size_t)s->num_vars+1,1);
    assert(present && open);
    for (uint32_t i=0;i<s->num_clauses;++i) {
        CRef cr=s->clauses[i];if(cr==INVALID_CLAUSE || clause_deleted(s->arena,cr))continue;
        const Lit *l=CLAUSE_LITS(s->arena,cr);uint32_t n=CLAUSE_SIZE(s->arena,cr);bool sat=false;
        for(uint32_t j=0;j<n;++j){present[var(l[j])]=1;if(lxor(s->values[var(l[j])],sign(l[j]))==TRUE)sat=true;}
        if(!sat)for(uint32_t j=0;j<n;++j)open[var(l[j])]=1;
    }
    unsigned root=0,eliminated=0,absent=0,satisfied_only=0,active=0;
    for(Var v=1;v<=s->num_vars;++v){
        if(s->values[v]!=UNDEF){++root;continue;}
        if(elim_is_eliminated(s,v)){++eliminated;continue;}
        if(!present[v])++absent;else if(!open[v])++satisfied_only;else ++active;
    }
    printf("{\"result\":%d,\"variables\":%u,\"root_assigned\":%u,\"eliminated_unassigned\":%u,\"absent_unassigned\":%u,\"satisfied_only_unassigned\":%u,\"active_unassigned\":%u,\"decisions\":%llu,\"conflicts\":%llu}\n",result,s->num_vars,root,eliminated,absent,satisfied_only,active,(unsigned long long)s->stats.decisions,(unsigned long long)s->stats.conflicts);
    free(present);free(open);solver_free(s);return 0;
}
